func (o *SettlementAdjustment) Preload(name string, retrieved any) error {
	if o == nil {
		return nil
	}

	switch name {
	case "Household":
		rel, ok := retrieved.(*Household)
		if !ok {
			return fmt.Errorf("settlementAdjustment cannot load %T as %q", retrieved, name)
		}

		o.R.Household = rel
		o.R.Loaded.Household = true

		if rel != nil {
			rel.R.SettlementAdjustments = SettlementAdjustmentSlice{o}
		}
		return nil
	case "AccountingPeriod":
		rel, ok := retrieved.(*AccountingPeriod)
		if !ok {
			return fmt.Errorf("settlementAdjustment cannot load %T as %q", retrieved, name)
		}

		o.R.AccountingPeriod = rel
		o.R.Loaded.AccountingPeriod = true

		if rel != nil {
			rel.R.SettlementAdjustments = SettlementAdjustmentSlice{o}
		}
		return nil
	case "Member":
		rel, ok := retrieved.(*Member)
		if !ok {
			return fmt.Errorf("settlementAdjustment cannot load %T as %q", retrieved, name)
		}

		o.R.Member = rel
		o.R.Loaded.Member = true

		if rel != nil {
			rel.R.SettlementAdjustments = SettlementAdjustmentSlice{o}
		}
		return nil
	default:
		return fmt.Errorf("settlementAdjustment has no relationship %q", name)
	}
}

