// LoadHousehold loads the settlementAdjustment's Household into the .R struct
func (o *SettlementAdjustment) LoadHousehold(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.Household = nil
	o.R.Loaded.Household = false

	related, err := o.Household(mods...).One(ctx, exec)
	if err != nil {
		return err
	}

	related.R.SettlementAdjustments = SettlementAdjustmentSlice{o}

	o.R.Household = related
	o.R.Loaded.Household = true
	return nil
}

// LoadHousehold loads the settlementAdjustment's Household into the .R struct
func (os SettlementAdjustmentSlice) LoadHousehold(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	households, err := os.Household(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.Household = nil
		o.R.Loaded.Household = true
	}
	// O(N+M) stitch via a map keyed by the join column (key -> []parent; was O(N*M)).
	settlementAdjustmentByKey := make(map[uuid.UUID][]*SettlementAdjustment, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}

		settlementAdjustmentByKey[o.HouseholdID] = append(settlementAdjustmentByKey[o.HouseholdID], o)
	}

	for _, rel := range households {

		owners, ok := settlementAdjustmentByKey[rel.ID]
		if !ok {
			continue
		}

		for _, o := range owners {

			// to-one: keep only the first matching child (matches the previous break)
			if o.R.Household != nil {
				continue
			}

			rel.R.SettlementAdjustments = append(rel.R.SettlementAdjustments, o)

			o.R.Household = rel

		}
	}

	return nil
}

