// LoadAccountingPeriod loads the settlementAdjustment's AccountingPeriod into the .R struct
func (os SettlementAdjustmentSlice) LoadAccountingPeriod(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	accountingPeriods, err := os.AccountingPeriod(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.AccountingPeriod = nil
		o.R.Loaded.AccountingPeriod = true
	}
	for _, o := range os {
		if o == nil {
			continue
		}

		for _, rel := range accountingPeriods {

			if !(o.HouseholdID == rel.HouseholdID) {
				continue
			}

			if !(o.Period == rel.Period) {
				continue
			}

			rel.R.SettlementAdjustments = append(rel.R.SettlementAdjustments, o)

			o.R.AccountingPeriod = rel
			break
		}
	}

	return nil
}

